import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.*;import ghidra.program.model.symbol.*;import java.io.*;public class FontReferences extends GhidraScript{public void run()throws Exception{String[]a=getScriptArgs();try(PrintWriter w=new PrintWriter(a[0])){for(int i=1;i<a.length;i++)for(Reference x:getReferencesTo(toAddr(a[i]))){Function f=getFunctionContaining(x.getFromAddress());w.println(a[i]+"\t"+x.getFromAddress()+"\t"+(f==null?"NONE":f.getEntryPoint())+"\t"+x.getReferenceType());}}}}